style.css:
@-moz-document domain("zone.k12.com") {
/* Menu Styling */
  div.Row__RowStyles-gCQMvY.oTPeK {
    color: darkblue;
    background-color: darkblue;
  }

/* Current Button */
  button.MenuItem__MenuItemStyles-fXAnCw.ergseU {
    color: darkblue;
    background-color: darkblue;
    transition: all 0.3s ease;
  }

/* Button When Hovered */
  button.MenuItem__MenuItemStyles-fXAnCw.hExSwg:hover {
    color: blue;
    background-color: blue;
    transition: all 0.3s ease;
  }

/* Blue Messages for the left side */
  div.Message__MessageStyles-begkfs.jRcCPJ,
  div.Message__MessageStyles-begkfs.kicNrR {
    color: white;
    background-color: cornflowerblue;
  }

/* Cyan Messages for the right side */
  div.Message__MessageStyles-begkfs.eGPjWz,
  div.Message__MessageStyles-begkfs.fKBjiH {
    color: white;
    background-color: cyan;
  }

/* Side menu */
  div.Grid__GridStyles-dZNEmg.bQeRgO.menu {
    background-color: darkblue;
  }

/* Top pieces */
  div.Grid__GridStyles-dZNEmg.csgYyo,
  div.PageHeader__PageHeaderStyles-gaLmko.iIxmwK {
    background-color: blue;
  }

/* Top text */
  h3.Typography__H3Styles-gBtyoY.hNRFCH,
  
button.Button__TextButtonStyles-fzLYtp.jYcJUZ {
    
color: white;
  }

/* Friends Online list outline */
  div.Grid__GridStyles-dZNEmg.bCjjA-d {
    outline-style: solid;
    outline-color: #8f8f8f;
    outline-width: 3px;
  }

/* Right-side menu in Worlds */
  div.Col__ColStyles-fRMNOg.eQdKMd {
    background: linear-gradient(0deg, rgba(0, 0, 255, 1) 1%, rgba(130, 84, 255, 1) 100%);
  }

/* Pop-ups */
  div.Card__CardStyles-kslYiw.clNnnc {
    background: linear-gradient(45deg, rgba(255, 255, 255, 1) 0%, rgba(230, 230, 230, 1) 100%);
  }

/* Continue button area */
  div.Modal__FooterStyles-gXXlMq.kqXGYy {
    outline-style: dotted;
    outline-color: rgba(230, 230, 230, 1);
  }

/* Pop-up X button */
  button.IconButton__IconButtonStyles-frQRdk.dkUWJP {
    background-color: red;
  }

/* Continue button hover outline */
  button.Button__SharedButtonStyles-lmUfFJ.Button__ButtonStyles-cYhuwE.ckdiVx.kjGtFr:hover {
    outline-style: solid;
    outline-color: darkgray;
  }

/* Enter World button hover */
  button.Button__SharedButtonStyles-lmUfFJ.Button__ButtonStyles-cYhuwE.ckdiVx.kaCeNT:hover {
    transition: all 0.5s ease-out;
    background-color: orange;
  }

/* Side-panel top */
  div.Row__RowStyles-gCQMvY.fmFqyd.drawer-header {
    background: linear-gradient(90deg, rgba(175, 171, 255, 1) 0%, rgba(164, 128, 255, 1) 100%);
  }

/* Buttons in panel */
  button.IconButton__IconButtonStyles-frQRdk.icoXSI {
    transition: all 0.2s ease-in;
  }

/* Panel buttons hover outline */
  button.IconButton__IconButtonStyles-frQRdk.icoXSI:hover {
    outline-color: gray;
    outline-style: solid;
    outline-width: 3px;
  }

/* Rounded Details and Avatar sections */
  .Grid__GridStyles-dZNEmg > #accordion > .Row__RowStyles-gCQMvY,
  .Row__RowStyles-gCQMvY > #accordion > .Row__RowStyles-gCQMvY {
    border-radius: 10px;
  }
}
